//! The narrow shadcn Nova Dialog visual port.
//!
//! Visual source: shadcn/ui 4.19.0 `dialog.tsx` and `style-nova.css` at
//! `1773ecfeeb4a04366978d353e69b5c7ded78dcb2`. Interaction, dismissal, and the
//! Popup/Close focus cycle come from the pinned Base GPUI Dialog primitives.

#[path = "modal_focus.rs"]
pub(crate) mod modal_focus;

pub use base_gpui::dialog::{
    DialogBackdrop, DialogClose, DialogDescription, DialogPopup, DialogPortal, DialogRoot,
    DialogTitle, DialogTrigger, DialogViewport,
};
use gpui::{App, Div, ElementId, FontWeight, ParentElement as _, SharedString, Styled, div, px};
use gpui_icons::{LucideIcon, lucide};

use super::{
    button::{ButtonSize, ButtonVariant, style_button},
    theme::UiTheme,
};

/// Creates the Dialog state root with a caller-owned stable ID.
/// An internal handle reconciles controlled focus. If replacing `.handle(...)`,
/// drive open/close transitions through the supplied handle.
pub fn dialog_root(id: impl Into<ElementId>) -> DialogRoot<()> {
    let id = id.into();
    let handle = base_gpui::dialog::DialogHandle::new();
    DialogRoot::new()
        .id(id.clone())
        .handle(handle.clone())
        .child_any(modal_focus::RootFocus::new(id, handle))
}

/// Creates a styled Dialog trigger with a caller-owned stable ID.
pub fn dialog_trigger(id: impl Into<ElementId>, cx: &App) -> DialogTrigger<()> {
    let theme = UiTheme::read(cx).clone();
    DialogTrigger::new()
        .id(id)
        .style_with_state(move |state, base| {
            style_button(
                base,
                state.disabled,
                ButtonVariant::Outline,
                ButtonSize::Default,
                &theme,
            )
        })
}

/// Creates the in-canvas Dialog portal.
pub fn dialog_portal() -> DialogPortal<()> {
    DialogPortal::new()
}

/// Creates the dismissible, full-window Dialog backdrop.
pub fn dialog_backdrop(cx: &App) -> DialogBackdrop<()> {
    DialogBackdrop::new()
        .absolute()
        .inset_0()
        .bg(UiTheme::read(cx).colors.overlay)
}

/// Creates the centered Dialog viewport with the pinned 16px page gutter.
pub fn dialog_viewport(cx: &App) -> DialogViewport<()> {
    let theme = UiTheme::read(cx).clone();
    let spacing = theme.spacing.unit;
    DialogViewport::new()
        .absolute()
        .inset_0()
        .flex()
        .flex_col()
        .items_stretch()
        .justify_center()
        .p(spacing * 4_f32)
}

/// Creates Nova's stacked Dialog header.
pub fn dialog_header(cx: &App) -> Div {
    let theme = UiTheme::read(cx).clone();
    let spacing = theme.spacing.unit;
    div().flex().flex_col().gap(spacing * 2_f32)
}

/// Creates Nova's inset Dialog footer surface.
pub fn dialog_footer(cx: &App) -> Div {
    let theme = UiTheme::read(cx);
    let spacing = theme.spacing.unit;
    div()
        .mx(spacing * -4_f32)
        .mb(spacing * -4_f32)
        .flex()
        .justify_end()
        .gap(spacing * 2_f32)
        .rounded_b(theme.radius.xl)
        .border_t_1()
        .border_color(theme.colors.border)
        .bg(theme.colors.muted.opacity(0.50))
        .p(spacing * 4_f32)
}

/// Creates a styled Dialog popup with a caller-owned stable ID and name.
pub fn dialog_popup(
    id: impl Into<ElementId>,
    aria_label: impl Into<SharedString>,
    cx: &App,
) -> DialogPopup<()> {
    let theme = UiTheme::read(cx).clone();
    let spacing = theme.spacing.unit;
    let text_scale = theme.text_scale;
    let id = id.into();
    let focus = modal_focus::ModalFocus::new(id.clone());
    DialogPopup::new()
        .id(id)
        .aria_label(aria_label)
        .child_any(focus.boundary(false))
        .child_any(focus.boundary(true))
        .style_with_state(move |state, base| {
            let base = focus.trap(
                base,
                state.modal_mode.traps_focus() && !state.nested_dialog_open,
            );
            base.w_full()
                .min_w(px(0.))
                .mx_auto()
                .max_w(spacing * 96_f32)
                .max_h(spacing * 100_f32)
                .overflow_hidden()
                .flex()
                .flex_col()
                .gap(spacing * 4_f32)
                .rounded(theme.radius.xl)
                .border_1()
                .border_color(theme.colors.foreground.opacity(0.10))
                .p(spacing * 4_f32)
                .bg(theme.colors.popover)
                .text_color(theme.colors.popover_foreground)
                .font_family(theme.fonts.body.clone())
                .text_size(px(14.0) * text_scale)
        })
}

/// Creates a styled Dialog title with a caller-owned stable ID.
pub fn dialog_title(id: impl Into<ElementId>, cx: &App) -> DialogTitle<()> {
    let theme = UiTheme::read(cx).clone();
    let text_scale = theme.text_scale;
    DialogTitle::new()
        .id(id)
        .font_family(theme.fonts.heading)
        .font_weight(FontWeight::MEDIUM)
        .text_size(px(16.0) * text_scale)
        .line_height(px(16.0) * text_scale)
        .text_color(theme.colors.popover_foreground)
}

/// Creates a styled Dialog description with a caller-owned stable ID.
pub fn dialog_description(id: impl Into<ElementId>, cx: &App) -> DialogDescription<()> {
    let theme = UiTheme::read(cx).clone();
    let text_scale = theme.text_scale;
    DialogDescription::new()
        .id(id)
        .font_family(theme.fonts.body)
        .text_size(px(14.0) * text_scale)
        .text_color(theme.colors.muted_foreground)
}

/// Creates the styled, icon-only Dialog close control.
pub fn dialog_close(id: impl Into<ElementId>, cx: &App) -> DialogClose<()> {
    let theme = UiTheme::read(cx).clone();
    let spacing = theme.spacing.unit;
    let icon_color = theme.colors.popover_foreground;
    DialogClose::new()
        .id(id)
        .aria_label("Close")
        .absolute()
        .top(spacing * 2_f32)
        .right(spacing * 2_f32)
        .style_with_state(move |state, base| {
            style_button(
                base,
                state.disabled,
                ButtonVariant::Ghost,
                ButtonSize::IconSm,
                &theme,
            )
        })
        .child(
            lucide(LucideIcon::X)
                .size(spacing * 4_f32)
                .text_color(icon_color),
        )
}

/// Creates a primary Dialog action that dismisses the Dialog after activation.
pub fn dialog_action(id: impl Into<ElementId>, cx: &App) -> DialogClose<()> {
    let theme = UiTheme::read(cx).clone();
    DialogClose::new()
        .id(id)
        .style_with_state(move |state, base| {
            style_button(
                base,
                state.disabled,
                ButtonVariant::Default,
                ButtonSize::Default,
                &theme,
            )
        })
}

//! Modal keyboard traversal over GPUI's actual tab stops, including app-owned
//! inputs passed through Base GPUI's `child_any` slots.

use std::{
    cell::{Cell, RefCell},
    rc::Rc,
    sync::Arc,
};

use base_gpui::dialog::{DialogFocusNextAction, DialogFocusPreviousAction};
use gpui::{
    App, Div, ElementId, FocusHandle, InteractiveElement as _, IntoElement, RenderOnce,
    SharedString, Styled, Window, div, px,
};

/// Reconciles externally controlled transitions that Base's `sync_open_from_context`
/// does not send through its focus lifecycle. The Base root has already wired its
/// popup handles before rendering this zero-sized child.
#[derive(IntoElement)]
pub(crate) struct RootFocus {
    id: ElementId,
    handle: base_gpui::dialog::DialogHandle<()>,
}

impl RootFocus {
    pub(crate) fn new(id: ElementId, handle: base_gpui::dialog::DialogHandle<()>) -> Self {
        Self { id, handle }
    }
}

#[derive(Default)]
struct RootFocusState {
    open: bool,
    return_to: Option<FocusHandle>,
}

impl RenderOnce for RootFocus {
    fn render(self, window: &mut Window, cx: &mut App) -> impl IntoElement {
        let Some(context) = self.handle.context() else {
            // A caller-supplied handle owns Base's normal open/close focus flow.
            return div().absolute().size(px(0.));
        };
        let state = window.use_keyed_state(
            ElementId::NamedChild(Arc::new(self.id), "controlled-focus".into()),
            cx,
            |_, _| RootFocusState::default(),
        );
        let popup = context.read(cx, |runtime, _| runtime.popup_focus_neighbor(None, false));
        let open = context.read(cx, |runtime, props| {
            runtime.open_value() && props.modal_mode().traps_focus()
        });
        state.update(cx, |state, cx| {
            let inside = popup
                .as_ref()
                .is_some_and(|popup| popup.contains_focused(window, cx));
            if open && !state.open {
                if inside {
                    // A trigger or handle already ran Base's focus transition.
                    state.return_to =
                        context.read(cx, |runtime, _| runtime.previous_focus_handle());
                } else {
                    state.return_to = window.focused(cx);
                    context.update(cx, |runtime| {
                        runtime.capture_previous_focus(state.return_to.clone())
                    });
                    if let Some(popup) = &popup {
                        popup.focus(window, cx);
                    }
                }
            } else if !open && state.open {
                // Preserve focus explicitly moved by a close handler or by Base.
                if (inside || window.focused(cx).is_none())
                    && let Some(handle) = state.return_to.take()
                {
                    handle.focus(window, cx);
                }
                state.return_to = None;
            }
            state.open = open;
        });
        div().absolute().size(px(0.))
    }
}

#[derive(Clone)]
pub(crate) struct ModalFocus {
    id: ElementId,
    enabled: Rc<Cell<bool>>,
    handles: Rc<RefCell<[Option<FocusHandle>; 2]>>,
}

impl ModalFocus {
    pub(crate) fn new(id: ElementId) -> Self {
        Self {
            id,
            enabled: Rc::default(),
            handles: Rc::default(),
        }
    }

    pub(crate) fn boundary(&self, end: bool) -> impl IntoElement {
        Boundary {
            scope: self.clone(),
            end,
        }
    }

    pub(crate) fn trap(&self, base: Div, enabled: bool) -> Div {
        self.enabled.set(enabled);
        if !enabled {
            return base;
        }
        let next = self.clone();
        let previous = self.clone();
        // Child controls can resolve Tab to the shared fallback bindings.
        let fallback_next = self.clone();
        let fallback_previous = self.clone();
        base.tab_group()
            .capture_action(move |_: &super::super::theme::FocusNext, window, cx| {
                fallback_next.advance(false, window, cx)
            })
            .capture_action(move |_: &super::super::theme::FocusPrevious, window, cx| {
                fallback_previous.advance(true, window, cx)
            })
            .capture_action(move |_: &DialogFocusNextAction, window, cx| {
                next.advance(false, window, cx)
            })
            .capture_action(move |_: &DialogFocusPreviousAction, window, cx| {
                previous.advance(true, window, cx)
            })
    }

    fn advance(&self, reverse: bool, window: &mut Window, cx: &mut App) {
        let [Some(start), Some(end)] = self.handles.borrow().clone() else {
            return;
        };
        let original = window.focused(cx);
        if reverse {
            // The initially focused popup is the ancestor of both boundaries.
            // Enter from the end without focusing anything behind the modal.
            if start.within_focused(window, cx) {
                end.focus(window, cx);
            }
            window.focus_prev(cx);
            if start.is_focused(window) {
                end.focus(window, cx);
                window.focus_prev(cx);
            }
        } else {
            window.focus_next(cx);
            if start.is_focused(window) {
                window.focus_next(cx);
            }
            if end.is_focused(window) {
                start.focus(window, cx);
                window.focus_next(cx);
            }
        }
        if (start.is_focused(window) || end.is_focused(window))
            && let Some(original) = original
        {
            original.focus(window, cx);
        }
        window.prevent_default();
        cx.stop_propagation();
    }
}

#[derive(IntoElement)]
struct Boundary {
    scope: ModalFocus,
    end: bool,
}

impl RenderOnce for Boundary {
    fn render(self, window: &mut Window, cx: &mut App) -> impl IntoElement {
        let index = usize::from(self.end);
        let id = ElementId::NamedChild(
            Arc::new(self.scope.id),
            SharedString::from(if self.end { "tab-end" } else { "tab-start" }),
        );
        let handle = window
            .use_keyed_state(id.clone(), cx, |_, cx| cx.focus_handle())
            .read(cx)
            .clone();
        self.scope.handles.borrow_mut()[index] = Some(handle.clone());
        // Out of layout and role-less. The end's group index follows all normal
        // controls, including custom positive tab indices, although both boundaries are inserted first.
        div().id(id).absolute().size(px(0.)).track_focus(
            &handle
                .tab_stop(self.scope.enabled.get())
                .tab_index(if self.end { isize::MAX } else { 0 }),
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use gpui::{
        AppContext as _, Context, ParentElement as _, Render, TestAppContext,
        prelude::FluentBuilder as _,
    };

    struct ControlledView {
        open: bool,
        modal: bool,
        handle: Option<base_gpui::dialog::DialogHandle<()>>,
        outside: FocusHandle,
        first: FocusHandle,
        last: FocusHandle,
    }
    impl Render for ControlledView {
        fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
            use super::super::*;
            let view = cx.entity().downgrade();
            dialog_root("controlled-test")
                .open(self.open)
                .modal(self.modal)
                .map(|root| match &self.handle {
                    Some(handle) => root.handle(handle.clone()),
                    None => root,
                })
                .on_open_change(move |open, _, _, cx| {
                    let _ = view.update(cx, |view, cx| {
                        view.open = open;
                        cx.notify();
                    });
                })
                .child_any(
                    base_gpui::input::Input::new()
                        .id("outside-input")
                        .focus_handle(self.outside.clone()),
                )
                .child(dialog_trigger("trigger", cx).child("Open"))
                .child(
                    dialog_portal().child(
                        dialog_viewport(cx).child(
                            dialog_popup("controlled-popup", "Confirmation", cx)
                                .child_any(div().track_focus(&self.first).child("First"))
                                .child_any(div().track_focus(&self.last).child("Last")),
                        ),
                    ),
                )
        }
    }

    #[gpui::test]
    fn controlled_dialog_moves_traps_and_restores_focus(cx: &mut TestAppContext) {
        cx.update(super::super::super::theme::init);
        let outside = cx.update(|cx| cx.focus_handle().tab_stop(true));
        let first = cx.update(|cx| cx.focus_handle().tab_stop(true));
        let last = cx.update(|cx| cx.focus_handle().tab_stop(true));
        let window = cx.add_window({
            let (outside, first, last) = (outside.clone(), first.clone(), last.clone());
            move |_, _| ControlledView {
                open: false,
                modal: true,
                handle: None,
                outside,
                first,
                last,
            }
        });
        cx.update_window(window.into(), |_, window, cx| {
            window.activate_window();
            window.draw(cx).clear(cx);
            outside.focus(window, cx);
        })
        .unwrap();
        let set_open = |cx: &mut TestAppContext, open, modal| {
            cx.update_window(window.into(), |view, window, cx| {
                view.downcast::<ControlledView>()
                    .unwrap()
                    .update(cx, |view, cx| {
                        view.open = open;
                        view.modal = modal;
                        cx.notify();
                    });
                window.draw(cx).clear(cx);
            })
            .unwrap();
        };
        set_open(cx, true, true);
        for expected in [&first, &last, &first] {
            cx.simulate_keystrokes(window.into(), "tab");
            cx.update_window(window.into(), |_, window, cx| {
                assert!(
                    expected.is_focused(window),
                    "modal Tab must stay in popup; expected={expected:?} actual={:?}",
                    window.focused(cx)
                );
                assert!(!outside.is_focused(window));
            })
            .unwrap();
        }
        cx.simulate_keystrokes(window.into(), "escape");
        cx.update_window(window.into(), |view, window, cx| {
            assert!(!view.downcast::<ControlledView>().unwrap().read(cx).open);
            window.draw(cx).clear(cx);
            assert!(outside.is_focused(window), "Escape restores input focus");
        })
        .unwrap();
        set_open(cx, true, true);
        set_open(cx, false, true);
        cx.update_window(window.into(), |_, window, _| {
            assert!(
                outside.is_focused(window),
                "controlled close restores input focus"
            )
        })
        .unwrap();
        set_open(cx, true, false);
        cx.update_window(window.into(), |_, window, _| {
            assert!(
                outside.is_focused(window),
                "nonmodal opening must not steal focus"
            )
        })
        .unwrap();
        set_open(cx, false, true);
        cx.simulate_keystrokes(window.into(), "tab");
        cx.run_until_parked();
        let trigger = cx
            .update_window(window.into(), |_, window, cx| window.focused(cx).unwrap())
            .unwrap();
        cx.simulate_keystrokes(window.into(), "enter");
        cx.update_window(window.into(), |_, window, cx| {
            window.draw(cx).clear(cx);
            assert!(!trigger.is_focused(window), "trigger opens popup");
        })
        .unwrap();
        cx.simulate_keystrokes(window.into(), "escape");
        cx.update_window(window.into(), |_, window, cx| {
            window.draw(cx).clear(cx);
            assert!(
                trigger.is_focused(window),
                "trigger focus restoration remains intact"
            );
        })
        .unwrap();
        let handle = base_gpui::dialog::DialogHandle::new();
        cx.update_window(window.into(), |view, window, cx| {
            view.downcast::<ControlledView>()
                .unwrap()
                .update(cx, |view, cx| {
                    view.handle = Some(handle.clone());
                    cx.notify();
                });
            window.draw(cx).clear(cx);
            outside.focus(window, cx);
            assert!(handle.open("missing-trigger", window, cx));
            window.draw(cx).clear(cx);
            assert!(!outside.is_focused(window), "caller handle opens popup");
        })
        .unwrap();
        cx.simulate_keystrokes(window.into(), "escape");
        cx.update_window(window.into(), |_, window, cx| {
            window.draw(cx).clear(cx);
            assert!(
                outside.is_focused(window),
                "caller handle restores previous focus"
            );
        })
        .unwrap();
    }

    struct View {
        popup: FocusHandle,
        first: FocusHandle,
        last: FocusHandle,
        outside: FocusHandle,
        scope: ModalFocus,
        trap: bool,
    }
    impl Render for View {
        fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
            div().child(div().track_focus(&self.outside)).child(
                self.scope
                    .trap(
                        div()
                            .key_context(base_gpui::dialog::DIALOG_POPUP_KEY_CONTEXT)
                            .track_focus(&self.popup),
                        self.trap,
                    )
                    .child(self.scope.boundary(false))
                    .child(self.scope.boundary(true))
                    .child(div().track_focus(&self.first))
                    .child(div().track_focus(&self.last)),
            )
        }
    }

    #[test]
    fn modal_tab_order_includes_generic_children_and_wraps_both_ways() {
        let mut cx = TestAppContext::single();
        cx.update(super::super::super::theme::init);
        let (popup, first, last, outside) = cx.update(|cx| {
            (
                cx.focus_handle().tab_stop(true),
                cx.focus_handle().tab_stop(true),
                cx.focus_handle().tab_stop(true),
                cx.focus_handle().tab_stop(true),
            )
        });
        let scope = ModalFocus::new("test-modal".into());
        let window = cx.add_window({
            let (popup, first, last, outside, scope) = (
                popup.clone(),
                first.clone(),
                last.clone(),
                outside.clone(),
                scope.clone(),
            );
            move |_, _| View {
                popup,
                first,
                last,
                outside,
                scope,
                trap: true,
            }
        });
        cx.update_window(window.into(), |_, window, cx| {
            window.draw(cx).clear(cx);
            popup.focus(window, cx);
        })
        .unwrap();
        for (keys, expected) in [
            ("tab", &first),
            ("tab", &last),
            ("tab", &first),
            ("shift-tab", &last),
            ("shift-tab", &first),
        ] {
            cx.simulate_keystrokes(window.into(), keys);
            cx.update_window(window.into(), |_, window, _| {
                assert!(expected.is_focused(window), "{keys}");
                assert!(!outside.is_focused(window));
            })
            .unwrap();
        }
        cx.update_window(window.into(), |_, window, cx| {
            popup.focus(window, cx);
            scope.advance(true, window, cx);
            assert!(last.is_focused(window));
        })
        .unwrap();
        cx.update_window(window.into(), |view, window, cx| {
            view.downcast::<View>()
                .unwrap()
                .update(cx, |view, _| view.trap = false);
            window.draw(cx).clear(cx);
            popup.focus(window, cx);
            window.focus_next(cx);
            assert!(
                first.is_focused(window),
                "non-modal traversal must skip hidden boundaries"
            );
        })
        .unwrap();
    }
}

//! The shadcn Nova Drawer visual port.
//!
//! Drag dismissal, snap points, nesting, and modal focus behavior stay in Base GPUI.

pub use base_gpui::drawer::{
    DrawerBackdrop, DrawerClose, DrawerContent, DrawerDescription, DrawerPopup, DrawerPortal,
    DrawerRoot, DrawerSwipeDirection, DrawerTitle, DrawerTrigger, DrawerViewport,
};
use gpui::{App, Div, ElementId, FontWeight, SharedString, Styled, div, px};

use super::{
    button::{ButtonSize, ButtonVariant, style_button},
    dialog::modal_focus::ModalFocus,
    theme::UiTheme,
};

/// Creates a Drawer root with a caller-owned stable ID.
pub fn drawer_root(id: impl Into<ElementId>) -> DrawerRoot<()> {
    DrawerRoot::new().id(id)
}

/// Creates an outline Drawer trigger.
pub fn drawer_trigger(id: impl Into<ElementId>, cx: &App) -> DrawerTrigger<()> {
    let theme = UiTheme::read(cx).clone();
    DrawerTrigger::new()
        .id(id)
        .style_with_state(move |state, base| {
            style_button(
                base,
                state.disabled,
                ButtonVariant::Outline,
                ButtonSize::Default,
                &theme,
            )
        })
}

/// Creates the portal for Drawer layers.
pub fn drawer_portal() -> DrawerPortal<()> {
    DrawerPortal::new()
}

/// Creates the Nova modal backdrop.
pub fn drawer_backdrop(cx: &App) -> DrawerBackdrop<()> {
    DrawerBackdrop::new()
        .absolute()
        .inset_0()
        .bg(UiTheme::read(cx).colors.overlay)
}

/// Creates the full-window Drawer viewport.
pub fn drawer_viewport() -> DrawerViewport<()> {
    DrawerViewport::new()
        .absolute()
        .inset_0()
        .style_with_state(|state, base| match state.swipe_direction {
            DrawerSwipeDirection::Down => base.flex().flex_col().justify_end(),
            DrawerSwipeDirection::Up => base.flex().flex_col().justify_start(),
            DrawerSwipeDirection::Left => base.flex().justify_start(),
            DrawerSwipeDirection::Right => base.flex().justify_end(),
        })
}

/// Creates the side-aware Drawer surface. The root's swipe direction controls its edge.
pub fn drawer_popup(
    id: impl Into<ElementId>,
    aria_label: impl Into<SharedString>,
    cx: &App,
) -> DrawerPopup<()> {
    let theme = UiTheme::read(cx).clone();
    let spacing = theme.spacing.unit;
    let text_scale = theme.text_scale;
    let id = id.into();
    let focus = ModalFocus::new(id.clone());
    DrawerPopup::new()
        .id(id)
        .aria_label(aria_label)
        .child_any(focus.boundary(false))
        .child_any(focus.boundary(true))
        .style_with_state(move |state, base| {
            let base = focus.trap(
                base,
                state.modal_mode.traps_focus() && !state.nested_drawer_open,
            );
            let surface = base
                .overflow_hidden()
                .bg(theme.colors.popover)
                .text_color(theme.colors.popover_foreground)
                .font_family(theme.fonts.body.clone())
                .text_size(px(14.0) * text_scale);
            match state.swipe_direction {
                DrawerSwipeDirection::Down => surface
                    .w_full()
                    .max_h(spacing * 100_f32)
                    .rounded_t(theme.radius.xl)
                    .border_t_1(),
                DrawerSwipeDirection::Up => surface
                    .w_full()
                    .max_h(spacing * 100_f32)
                    .rounded_b(theme.radius.xl)
                    .border_b_1(),
                DrawerSwipeDirection::Left => surface
                    .h_full()
                    .w(spacing * 80_f32)
                    .rounded_r(theme.radius.xl)
                    .border_r_1(),
                DrawerSwipeDirection::Right => surface
                    .h_full()
                    .w(spacing * 80_f32)
                    .rounded_l(theme.radius.xl)
                    .border_l_1(),
            }
            .border_color(theme.colors.border)
        })
}

/// Creates the padded Drawer content container.
pub fn drawer_content(cx: &App) -> DrawerContent<()> {
    let theme = UiTheme::read(cx).clone();
    DrawerContent::new().style_with_state(move |_state, base| {
        base.flex()
            .flex_col()
            .overflow_hidden()
            .bg(theme.colors.popover)
            .text_color(theme.colors.popover_foreground)
    })
}

/// Creates Nova's non-interactive vertical swipe handle.
pub fn drawer_swipe_handle(cx: &App) -> Div {
    let theme = UiTheme::read(cx).clone();
    let spacing = theme.spacing.unit;
    div()
        .mx_auto()
        .mt(spacing * 4_f32)
        .h(spacing * 1_f32)
        .w(spacing * 24_f32)
        .rounded_full()
        .bg(theme.colors.muted)
}

/// Creates a Drawer title.
pub fn drawer_title(id: impl Into<ElementId>, cx: &App) -> DrawerTitle<()> {
    let theme = UiTheme::read(cx).clone();
    let text_scale = theme.text_scale;
    DrawerTitle::new()
        .id(id)
        .font_family(theme.fonts.heading)
        .font_weight(FontWeight::MEDIUM)
        .text_size(px(16.0) * text_scale)
        .text_color(theme.colors.foreground)
}

/// Creates a Drawer description.
pub fn drawer_description(id: impl Into<ElementId>, cx: &App) -> DrawerDescription<()> {
    let theme = UiTheme::read(cx).clone();
    let text_scale = theme.text_scale;
    DrawerDescription::new()
        .id(id)
        .font_family(theme.fonts.body)
        .text_size(px(14.0) * text_scale)
        .text_color(theme.colors.muted_foreground)
}

/// Creates an outline Drawer close action.
pub fn drawer_close(id: impl Into<ElementId>, cx: &App) -> DrawerClose<()> {
    let theme = UiTheme::read(cx).clone();
    DrawerClose::new()
        .id(id)
        .style_with_state(move |state, base| {
            style_button(
                base,
                state.disabled,
                ButtonVariant::Outline,
                ButtonSize::Default,
                &theme,
            )
        })
}
